import "fmt"

func isPalindrome(s string) bool {
	runes := []rune(s)
	for i := 0; i < len(runes); i++ {
		if runes[i] != runes[len(runes)-1-i] {
			return false
		}
	}
	return true
}

func main() {
	fmt.Println(isPalindrome("racecar"))
	fmt.Println(isPalindrome("hello"))
}

